(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.02+t*0.3)*15+Math.cos(y*0.015-t*0.2)*10;
  const w1y = Math.cos(y*0.02-t*0.25)*15+Math.sin(x*0.018+t*0.35)*10;
  const w2x = Math.sin(y*0.012+t*0.5)*8+Math.cos(x*0.008-t*0.15)*12;
  const w2y = Math.cos(x*0.014-t*0.4)*8+Math.sin(y*0.01+t*0.6)*12;
  const sx = x+w1x+w2x, sy = y+w1y+w2y;
  const src = [
    [160+Math.sin(t*0.6)*100,80+Math.cos(t*0.4)*50,0.08,2.0,0],
    [320+Math.cos(t*0.5)*100,160+Math.sin(t*0.7)*50,0.1,1.7,1.2],
    [240+Math.sin(t*0.3+2)*140,120+Math.cos(t*0.5+1)*90,0.06,2.3,2.5],
    [120+Math.cos(t*0.8+1)*80,180+Math.sin(t*0.6+3)*60,0.12,1.5,3.7],
    [360+Math.sin(t*0.4+4)*90,60+Math.cos(t*0.9+2)*70,0.07,2.6,5.1],
    [240+Math.cos(t*0.35+5)*120,200+Math.sin(t*0.55)*80,0.09,1.9,0.8],
    [80+Math.sin(t*0.45+3)*70,40+Math.cos(t*0.65)*90,0.11,2.1,4.3],
    [400+Math.cos(t*0.55+2)*60,220+Math.sin(t*0.75+1)*50,0.05,2.8,1.6]
  ];
  let aS=0,iS=0,aS2=0,iS2=0;
  for(const[sX,sY,f,sp,ph]of src){
    const d=Math.sqrt((sx-sX)**2+(sy-sY)**2);
    const d2=Math.sqrt((sx-sX*0.6+80)**2+(sy-sY*0.6+40)**2);
    aS+=Math.sin(d*f-t*sp+ph);
    iS+=Math.sin(d*f*0.7+t*sp*0.6+1.5);
    aS2+=Math.sin(d2*f*1.3-t*sp*0.8+ph*0.5);
    iS2+=Math.cos(d2*f*0.5+t*sp*0.4+ph);
  }
  const act=aS/8,inh=iS/8,act2=aS2/8,inh2=iS2/8;
  const bg=(Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1))/2
    +Math.sin((sx+sy)*0.12+t*2.5)*0.2+Math.sin((sx-sy)*0.1-t*2)*0.2;
  const bg2=(Math.sin(sx*0.07-sy*0.05+t*1.3)+Math.cos(sx*0.05+sy*0.08-t*0.9))/2*0.4;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2),ang=Math.atan2(sy-cy,sx-cx);
  const spiral=(Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2))*0.4;
  const spiral2=(Math.cos(dist*0.07+ang*2-t*2)+Math.sin(dist*0.03-ang*5+t*1.8))*0.2;
  const wave=Math.sin(sx*0.06+t*1.5)*Math.cos(sy*0.05-t*1.2)*0.3;
  const r1=Math.tanh((act-inh*0.7+bg*0.3+spiral)*2.2);
  const r2=Math.tanh((act2*0.8-inh2*0.6+bg2+spiral2+wave)*1.8);
  const coupled=Math.tanh(r1*1.5+r2*0.8+r1*r2*0.6);
  const cell=Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15)+Math.sin((sx+sy)*0.1+t)*0.5)*1.5)*0.3;
  const cell2=Math.tanh((Math.cos(sx*0.22-t*0.5)*Math.sin(sy*0.18+t*0.7)+Math.sin(sx*0.08-sy*0.12+t*0.3)*0.4)*1.2)*0.15;
  const blend=coupled*0.6+cell*0.25+cell2*0.15,v=blend*0.5+0.5;
  const hueShift=Math.sin(t*0.15)*0.15+Math.sin(coupled*2+t*0.3)*0.1;
  const pal=[
    [12,8,42],[18,28,82],[20,65,115],[25,120,130],
    [80,165,120],[180,190,80],[220,165,60],[210,110,55],
    [185,60,60],[140,30,65],[85,18,55],[12,8,42]
  ];
  const idx=Math.max(0,Math.min(1,v+hueShift))*(pal.length-1);
  const i=Math.min(idx|0,pal.length-2),f=idx-i;
  const lum=0.75+Math.sin(coupled*Math.PI)*0.25;
  const edge=Math.abs(coupled)>0.75?1.2:Math.abs(coupled)>0.5?1.08:1.0;
  const glow=Math.max(0,coupled)*0.15;
  return[
    Math.min(255,((pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum*edge+glow*60)|0),
    Math.min(255,((pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*edge+glow*40)|0),
    Math.min(255,((pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum*edge+glow*80)|0)
  ];
}
